from pathlib import Path

PAGE = Path("pages/7_Manual_Planning_with_Interests.py")

if not PAGE.exists():
    raise SystemExit(
        "Run this from the PTMC-Rostering repository root."
    )

text = PAGE.read_text()

IMPORT_ANCHOR = 'from roster_engine.manual_planning_repository import ManualPlanningRepository\n'
IMPORT_REPLACEMENT = 'from roster_engine.manual_planning_repository import ManualPlanningRepository\nfrom roster_engine.fc_manual_continuity import (\n    availability_conflict_dates,\n    build_fc_segment_payloads,\n    group_fc_segments,\n    is_active_fc_requirement,\n    segment_overlap_dates,\n    uncovered_fc_dates,\n)\n'
COVER_BLOCK_START = 'with cover_tab:\n'
COVER_BLOCK_END = 'with interest_tab:\n'
INTEGRATED_COVER_BLOCK = 'with cover_tab:\n    st.subheader("Lock a cover assignment")\n    st.caption(\n        "Selections and conflict warnings update immediately. "\n        "FC continuity options appear only when an active FC requirement "\n        "is selected."\n    )\n\n    if not cover_requirements:\n        st.info("No cover requirements exist for this month.")\n    elif not cover_fit_names:\n        st.warning("No active Cover Fit personnel are available.")\n    else:\n        cover_date = st.date_input(\n            "Cover date",\n            value=selected_month,\n            min_value=selected_month,\n            max_value=selected_month_end,\n            format="DD/MM/YYYY",\n            key="manual_cover_date",\n        )\n\n        available_requirements = [\n            req\n            for req in cover_requirements\n            if req.includes_date(cover_date)\n        ]\n\n        cover_fit_options = personnel_available_on(\n            person_by_name,\n            cover_date,\n            cover_fit_only=True,\n        )\n\n        if not available_requirements:\n            st.info("No cover requirements exist on this date.")\n        elif not cover_fit_options:\n            st.warning(\n                "No active Cover Fit personnel remain eligible on this date "\n                "after applying leaving dates."\n            )\n        else:\n            requirement_by_id = {\n                req.id: req\n                for req in available_requirements\n            }\n\n            selected_requirement_id = st.selectbox(\n                "Cover requirement",\n                options=list(requirement_by_id),\n                format_func=lambda req_id: (\n                    f"{requirement_by_id[req_id].requesting_unit} — "\n                    f"{requirement_by_id[req_id].cover_type} "\n                    f"({SESSION_LABELS.get(requirement_by_id[req_id].session, requirement_by_id[req_id].session)})"\n                ),\n            )\n\n            selected_requirement = requirement_by_id[\n                selected_requirement_id\n            ]\n\n            selected_is_fc = is_active_fc_requirement(\n                selected_requirement\n            )\n\n            if selected_is_fc:\n                assignment_mode = st.radio(\n                    "Assignment",\n                    [\n                        "Active FC",\n                        "FC reserve",\n                    ],\n                    horizontal=True,\n                    key=(\n                        "manual_fc_assignment_mode_"\n                        + selected_requirement_id\n                    ),\n                )\n            else:\n                assignment_mode = "Active cover"\n\n            # ---------------------------------------------------------------\n            # ACTIVE FC: continuity UI appears only when FC is selected.\n            # ---------------------------------------------------------------\n            if (\n                selected_is_fc\n                and assignment_mode == "Active FC"\n            ):\n                st.info(\n                    "FC continuity mode: the selected medic is assumed to "\n                    "cover continuously for the chosen period. Choose Whole FC "\n                    "or define a handover segment."\n                )\n\n                existing_segments = group_fc_segments(\n                    requirement_id=selected_requirement.id,\n                    assignments=manual_assignments,\n                )\n\n                uncovered_dates = uncovered_fc_dates(\n                    requirement=selected_requirement,\n                    assignments=manual_assignments,\n                )\n\n                if existing_segments:\n                    st.markdown("#### Current FC continuity plan")\n\n                    st.dataframe(\n                        [\n                            {\n                                "Personnel": segment.person_name,\n                                "From": segment.start_date,\n                                "Until": segment.end_date,\n                                "Days": segment.day_count,\n                                "Override": segment.allow_override,\n                                "Remarks": segment.remarks or "",\n                            }\n                            for segment in existing_segments\n                        ],\n                        use_container_width=True,\n                        hide_index=True,\n                        column_config={\n                            "From": st.column_config.DateColumn(\n                                "From",\n                                format="DD MMM",\n                            ),\n                            "Until": st.column_config.DateColumn(\n                                "Until",\n                                format="DD MMM",\n                            ),\n                        },\n                    )\n\n                    delete_segment_index = st.selectbox(\n                        "FC segment to remove",\n                        options=list(range(len(existing_segments))),\n                        format_func=lambda index: (\n                            f"{existing_segments[index].person_name}: "\n                            f"{existing_segments[index].start_date:%d %b} "\n                            f"→ {existing_segments[index].end_date:%d %b}"\n                        ),\n                        key=(\n                            "manual_fc_delete_segment_"\n                            + selected_requirement.id\n                        ),\n                    )\n\n                    if st.button(\n                        "Delete selected FC segment",\n                        use_container_width=True,\n                        key=(\n                            "manual_fc_delete_button_"\n                            + selected_requirement.id\n                        ),\n                    ):\n                        segment = existing_segments[\n                            delete_segment_index\n                        ]\n\n                        try:\n                            for assignment_id in segment.assignment_ids:\n                                (\n                                    get_supabase()\n                                    .table("roster_manual_assignments")\n                                    .delete()\n                                    .eq("id", assignment_id)\n                                    .execute()\n                                )\n                        except Exception as exc:\n                            st.error(\n                                f"Unable to delete FC segment: {exc}"\n                            )\n                        else:\n                            clear_manual_cache()\n                            st.success("FC segment deleted.")\n                            st.rerun()\n\n                if uncovered_dates:\n                    st.caption(\n                        f"{len(uncovered_dates)} FC day(s) remain manually "\n                        "uncovered. The generator may fill them using normal "\n                        "FC continuity."\n                    )\n                else:\n                    st.success(\n                        "The full FC requirement is manually covered."\n                    )\n\n                st.markdown("#### Add / define FC continuity")\n\n                duration_mode = st.radio(\n                    "FC duration",\n                    [\n                        "Whole FC",\n                        "Custom segment",\n                    ],\n                    horizontal=True,\n                    key=(\n                        "manual_fc_duration_mode_"\n                        + selected_requirement.id\n                    ),\n                )\n\n                if duration_mode == "Whole FC":\n                    fc_start = selected_requirement.start_date\n                    fc_end = selected_requirement.end_date\n\n                    st.caption(\n                        f"{fc_start:%d %b %Y} → {fc_end:%d %b %Y}"\n                    )\n                else:\n                    d1, d2 = st.columns(2)\n\n                    with d1:\n                        fc_start = st.date_input(\n                            "Cover from",\n                            value=max(\n                                cover_date,\n                                selected_requirement.start_date,\n                            ),\n                            min_value=selected_requirement.start_date,\n                            max_value=selected_requirement.end_date,\n                            format="DD/MM/YYYY",\n                            key=(\n                                "manual_fc_start_"\n                                + selected_requirement.id\n                            ),\n                        )\n\n                    with d2:\n                        fc_end = st.date_input(\n                            "Cover until",\n                            value=selected_requirement.end_date,\n                            min_value=fc_start,\n                            max_value=selected_requirement.end_date,\n                            format="DD/MM/YYYY",\n                            key=(\n                                "manual_fc_end_"\n                                + selected_requirement.id\n                                + "_"\n                                + fc_start.isoformat()\n                            ),\n                        )\n\n                fc_person_options = [\n                    name\n                    for name in cover_fit_names\n                    if (\n                        person_by_name[name].person.leaving_date\n                        is None\n                        or person_by_name[name].person.leaving_date\n                        > fc_end\n                    )\n                ]\n\n                fc_person = st.selectbox(\n                    "FC medic",\n                    options=fc_person_options,\n                    key=(\n                        "manual_fc_person_"\n                        + selected_requirement.id\n                        + "_"\n                        + fc_start.isoformat()\n                        + "_"\n                        + fc_end.isoformat()\n                    ),\n                    disabled=not fc_person_options,\n                )\n\n                fc_conflicts = (\n                    availability_conflict_dates(\n                        person_name=fc_person,\n                        start_date=fc_start,\n                        end_date=fc_end,\n                        availability_entries=availability_rows,\n                    )\n                    if fc_person\n                    else []\n                )\n\n                overlap_dates = segment_overlap_dates(\n                    requirement=selected_requirement,\n                    start_date=fc_start,\n                    end_date=fc_end,\n                    assignments=manual_assignments,\n                )\n\n                if fc_conflicts:\n                    st.warning(\n                        f"{fc_person} has Availability plotted on "\n                        f"{len(fc_conflicts)} selected day(s): "\n                        + ", ".join(\n                            current_date.strftime("%d %b")\n                            for current_date in fc_conflicts\n                        )\n                    )\n\n                if overlap_dates:\n                    st.error(\n                        "This segment overlaps an existing locked FC segment "\n                        "on: "\n                        + ", ".join(\n                            current_date.strftime("%d %b")\n                            for current_date in overlap_dates\n                        )\n                    )\n\n                allow_fc_override = st.checkbox(\n                    "Allow manual override for Availability conflicts",\n                    value=False,\n                    key=(\n                        "manual_fc_override_"\n                        + selected_requirement.id\n                        + "_"\n                        + fc_start.isoformat()\n                        + "_"\n                        + fc_end.isoformat()\n                    ),\n                )\n\n                fc_remarks = st.text_input(\n                    "Remarks",\n                    placeholder="Optional handover / FC note",\n                    key=(\n                        "manual_fc_remarks_"\n                        + selected_requirement.id\n                    ),\n                )\n\n                if st.button(\n                    "Lock FC continuity",\n                    type="primary",\n                    use_container_width=True,\n                    key=(\n                        "manual_fc_lock_"\n                        + selected_requirement.id\n                        + "_"\n                        + fc_start.isoformat()\n                        + "_"\n                        + fc_end.isoformat()\n                    ),\n                    disabled=(\n                        not fc_person_options\n                        or bool(overlap_dates)\n                        or (\n                            bool(fc_conflicts)\n                            and not allow_fc_override\n                        )\n                    ),\n                ):\n                    payloads = build_fc_segment_payloads(\n                        roster_month_id=roster_month_id,\n                        requirement=selected_requirement,\n                        person_name=fc_person,\n                        start_date=fc_start,\n                        end_date=fc_end,\n                        allow_override=allow_fc_override,\n                        remarks=fc_remarks,\n                    )\n\n                    try:\n                        (\n                            get_supabase()\n                            .table("roster_manual_assignments")\n                            .insert(payloads)\n                            .execute()\n                        )\n                    except Exception as exc:\n                        st.error(\n                            f"Unable to lock FC continuity: {exc}"\n                        )\n                    else:\n                        clear_manual_cache()\n                        st.success(\n                            f"FC continuity locked: {fc_person}, "\n                            f"{fc_start:%d %b} → {fc_end:%d %b}."\n                        )\n                        st.rerun()\n\n            # ---------------------------------------------------------------\n            # SINGLE-DAY COVER / FC RESERVE\n            # ---------------------------------------------------------------\n            else:\n                cover_person = st.selectbox(\n                    "Cover Fit personnel",\n                    cover_fit_options,\n                    key=(\n                        f"manual_cover_person_"\n                        f"{cover_date.isoformat()}_"\n                        f"{selected_requirement_id}_"\n                        f"{assignment_mode}"\n                    ),\n                )\n\n                availability_code = get_availability_code(\n                    availability_rows,\n                    cover_person,\n                    cover_date,\n                )\n\n                if availability_code:\n                    st.warning(\n                        f"{cover_person} has availability code "\n                        f"{availability_code} on "\n                        f"{cover_date:%d %b %Y}."\n                    )\n\n                allow_cover_override = st.checkbox(\n                    "Allow manual override if validation finds a conflict",\n                    value=False,\n                    key=(\n                        "manual_cover_override_"\n                        + selected_requirement_id\n                        + "_"\n                        + assignment_mode\n                    ),\n                )\n\n                cover_remarks = st.text_input(\n                    "Remarks",\n                    key=(\n                        "manual_cover_remarks_"\n                        + selected_requirement_id\n                        + "_"\n                        + assignment_mode\n                    ),\n                )\n\n                if st.button(\n                    "Lock cover assignment",\n                    type="primary",\n                    use_container_width=True,\n                    key=(\n                        "manual_cover_lock_button_"\n                        + selected_requirement_id\n                        + "_"\n                        + assignment_mode\n                    ),\n                ):\n                    kind = (\n                        "COVER_RESERVE"\n                        if (\n                            selected_is_fc\n                            and assignment_mode == "FC reserve"\n                        )\n                        else "COVER"\n                    )\n\n                    label = (\n                        "FC RESERVE"\n                        if kind == "COVER_RESERVE"\n                        else (\n                            f"{selected_requirement.requesting_unit} — "\n                            f"{selected_requirement.cover_type}"\n                        )\n                    )\n\n                    payload = {\n                        "roster_month_id": roster_month_id,\n                        "personnel_name": cover_person,\n                        "assignment_date": cover_date.isoformat(),\n                        "assignment_kind": kind,\n                        "centre": None,\n                        "role_name": None,\n                        "cover_requirement_id": selected_requirement_id,\n                        "cover_label": label,\n                        "session": selected_requirement.session,\n                        "is_locked": True,\n                        "allow_override": allow_cover_override,\n                        "remarks": cover_remarks.strip() or None,\n                    }\n\n                    try:\n                        (\n                            get_supabase()\n                            .table("roster_manual_assignments")\n                            .insert(payload)\n                            .execute()\n                        )\n                    except Exception as exc:\n                        st.error(\n                            f"Unable to save manual cover: {exc}"\n                        )\n                    else:\n                        clear_manual_cache()\n                        st.success("Cover assignment locked.")\n                        st.rerun()\n\n'

if "from roster_engine.fc_manual_continuity import" not in text:
    if IMPORT_ANCHOR not in text:
        raise SystemExit(
            "Could not find ManualPlanningRepository import."
        )
    text = text.replace(
        IMPORT_ANCHOR,
        IMPORT_REPLACEMENT,
        1,
    )

start = text.find(COVER_BLOCK_START)
end = text.find(COVER_BLOCK_END)

if start < 0 or end < 0 or end <= start:
    raise SystemExit(
        "Could not locate the current Manual Covers block."
    )

text = (
    text[:start]
    + INTEGRATED_COVER_BLOCK
    + text[end:]
)

compile(
    text,
    str(PAGE),
    "exec",
)

backup = PAGE.with_suffix(
    ".py.step22b_backup"
)

if not backup.exists():
    backup.write_text(
        PAGE.read_text()
    )

PAGE.write_text(text)

print(
    "Step 22B applied successfully."
)
print(
    "FC continuity now lives inside Manual Covers and appears only for FC."
)
